/** The device-typed-messages pattern's answer to one WeatherReport, sent by the app to the device that sent it. */
export interface WeatherReportAck
{
    Sequence: number;
    Accepted: boolean;
    Reason: string;
}

export const WEATHER_REPORT_ACK_VERSION = 1;
export const WEATHER_REPORT_ACK_OPCODE = 0x40000104;

const WEATHER_REPORT_ACK_REASON_FIELD_ID = 0x03F53591;
const WEATHER_REPORT_ACK_ACCEPTED_FIELD_ID = 0x42EAE5D9;
const WEATHER_REPORT_ACK_SEQUENCE_FIELD_ID = 0xF25158D3;

export function createWeatherReportAck(init?: Partial<WeatherReportAck>): WeatherReportAck
{
    const instance = {} as WeatherReportAck;
    resetWeatherReportAck(instance);
    if (init)
    {
        Object.assign(instance, init);
    }
    return instance;
}

export function resetWeatherReportAck(target: WeatherReportAck): WeatherReportAck
{
    target.Sequence = 0;
    target.Accepted = false;
    target.Reason = '';
    return target;
}

export function encodeWeatherReportAck(value: WeatherReportAck): Uint8Array
{
    const writer = new TeleportObjectWriter(WEATHER_REPORT_ACK_VERSION);
    writeToTeleportWeatherReportAck(value, writer);
    return writer.finish();
}

export function writeToTeleportWeatherReportAck(instance: WeatherReportAck, scope: TeleportObjectWriter): void
{
    scope.writeStringField(WEATHER_REPORT_ACK_REASON_FIELD_ID, instance.Reason);
    scope.writeBoolField(WEATHER_REPORT_ACK_ACCEPTED_FIELD_ID, instance.Accepted);
    scope.writeInt32Field(WEATHER_REPORT_ACK_SEQUENCE_FIELD_ID, (instance.Sequence | 0));
}

export function decodeWeatherReportAck(data: ArrayBuffer | Uint8Array, destination?: WeatherReportAck): WeatherReportAck
